        "suitable_envs": [
          "desc-python",
          "desc-cosmology"
        ],
        "duration_hint_s": 1800,
        "returns": "data vector rows, n(z), covariance diagonal, Fisher matrix (nested lists), fiducials, priors, derivatives, optional Fisher bias; sacc written in the job cwd"
      }
    }
  }
